import { useEffect, useState } from 'react';
import {
  Box,
  Typography,
  Grid,
  Stack,
  Chip,
} from '@mui/material';
import CheckCircleOutlineIcon from '@mui/icons-material/CheckCircleOutlineOutlined';
import BoltIcon from '@mui/icons-material/Bolt';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-hot-toast';
import GlowButton from '../components/ui/GlowButton';
import { PLANS } from '../constants/plans';
import { useSignup } from '../context/SignupContext';
import { selectPlan } from '../utils/planHelpers';
import { redirectToStripeCheckout } from '../utils/startCheckout';
import { BRAND, TOKENS } from '../theme';

const PlansPage = () => {
  const navigate = useNavigate();
  const { signupData, setSelectedPlan, setPlanLabel, entryFlow } = useSignup();
  const [loadingPlan, setLoadingPlan] = useState(null);

  useEffect(() => {
    if (!signupData?.email) {
      navigate('/app-signup', { replace: true });
      return;
    }
    if (entryFlow === 'plan-first') {
      navigate('/checkout', { replace: true });
    }
  }, [signupData, entryFlow, navigate]);

  useEffect(() => {
    window.history.pushState(null, '', window.location.href);
    const handlePopState = () => window.history.pushState(null, '', window.location.href);
    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, []);

  const handleSelect = async (plan) => {
    if (loadingPlan) return;

    const selection = selectPlan(plan, { setPlanLabel, setSelectedPlan });
    setLoadingPlan(plan.id);

    try {
      await redirectToStripeCheckout({
        plan: selection,
        customerEmail: signupData.email,
      });
    } catch (error) {
      toast.error(error.message || 'Unable to start checkout');
      setLoadingPlan(null);
    }
  };

  return (
    <Box sx={{ width: '100%', maxWidth: 960, mx: 'auto', px: { xs: 1.5, sm: 0 } }}>
      <Box sx={{ textAlign: 'center', mb: { xs: 4, sm: 6 } }}>
        <Chip
          icon={<BoltIcon sx={{ fontSize: 14, color: `${BRAND.trial} !important` }} />}
          label="7 DAYS FREE TRIAL ON BOTH PLANS"
          sx={{
            mb: 2,
            bgcolor: 'rgba(255, 196, 0, 0.1)',
            color: BRAND.trial,
            fontWeight: 800,
            fontSize: { xs: '0.62rem', sm: '0.68rem' },
            letterSpacing: '0.08em',
            border: '1px solid rgba(255, 196, 0, 0.35)',
          }}
        />
        <Typography
          variant="h3"
          sx={{
            fontWeight: 800,
            letterSpacing: '-0.03em',
            mb: 1.5,
            fontSize: { xs: '1.75rem', sm: '2.25rem' },
          }}
        >
          Choose your plan
        </Typography>
        <Typography variant="body1" sx={{ color: 'text.secondary', maxWidth: 480, mx: 'auto', px: 2 }}>
          Pick the plan that fits you best. Cancel anytime, no hidden fees.
        </Typography>
      </Box>

      <Grid container spacing={{ xs: 2.5, md: 3 }} justifyContent="center">
        {PLANS.map((plan) => (
          <Grid size={{ xs: 12, sm: 6 }} key={plan.id}>
            <Box
              sx={{
                height: '100%',
                display: 'flex',
                flexDirection: 'column',
                p: { xs: 3, sm: 4 },
                borderRadius: '28px',
                border: plan.featured ? `1.5px solid ${BRAND.green}` : `1px solid ${TOKENS.colors.border}`,
                bgcolor: plan.featured ? 'rgba(76,198,110,0.06)' : TOKENS.colors.surfaceElevated,
                boxShadow: plan.featured ? `0 16px 40px ${TOKENS.glow.lime}` : '0 8px 24px rgba(15, 23, 42, 0.06)',
                transition: 'all 0.45s cubic-bezier(0.23, 1, 0.32, 1)',
                '&:hover': {
                  transform: { xs: 'none', sm: 'translateY(-6px)' },
                  borderColor: BRAND.green,
                },
              }}
            >
              {plan.badge && (
                <Chip
                  label={plan.badge}
                  size="small"
                  sx={{
                    alignSelf: 'flex-end',
                    mb: 1,
                    bgcolor: BRAND.green,
                    color: '#FFFFFF',
                    fontWeight: 800,
                    fontSize: '0.65rem',
                  }}
                />
              )}

              <Typography
                sx={{
                  color: BRAND.green,
                  fontWeight: 800,
                  mb: 1.5,
                  textTransform: 'uppercase',
                  fontSize: '0.8rem',
                  letterSpacing: '0.1em',
                }}
              >
                {plan.name}
              </Typography>

              <Stack direction="row" alignItems="baseline" spacing={0.75} sx={{ mb: 2 }}>
                <Typography
                  sx={{
                    fontSize: { xs: '2.25rem', sm: '2.75rem' },
                    fontWeight: 900,
                    letterSpacing: '-0.04em',
                    lineHeight: 1,
                  }}
                >
                  {plan.price}
                </Typography>
                <Typography sx={{ color: 'text.secondary', fontWeight: 600 }}>{plan.period}</Typography>
              </Stack>

              <Typography variant="body2" sx={{ color: 'text.secondary', mb: 3, flexGrow: 1 }}>
                {plan.description}
              </Typography>

              <Stack spacing={1.25} sx={{ mb: 3 }}>
                {plan.features.map((f) => (
                  <Stack key={f} direction="row" alignItems="center" spacing={1}>
                    <CheckCircleOutlineIcon sx={{ color: BRAND.green, fontSize: 18, flexShrink: 0 }} />
                    <Typography variant="body2">{f}</Typography>
                  </Stack>
                ))}
              </Stack>

              <GlowButton
                fullWidth
                variant={plan.featured ? 'contained' : 'outlined'}
                onClick={() => handleSelect(plan)}
                disabled={Boolean(loadingPlan)}
              >
                {loadingPlan === plan.id ? 'Redirecting…' : plan.cta}
              </GlowButton>
            </Box>
          </Grid>
        ))}
      </Grid>
    </Box>
  );
};

export default PlansPage;
