export const planToSelection = (plan) => ({
  id: plan.id,
  name: plan.name,
  price: plan.price,
  period: plan.period,
  planId: plan.planId,
  lookupKey: plan.lookupKey,
  priceId: plan.priceId || null,
});

export const planBillingLabel = (planId) => (planId === 'annual' ? 'Yearly' : 'Monthly');

export const selectPlan = (plan, { setPlanLabel, setSelectedPlan }) => {
  setPlanLabel(planBillingLabel(plan.id));
  const selection = planToSelection(plan);
  setSelectedPlan(selection);
  return selection;
};
